"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/charts/variants/01-stacked-bar";
export interface ArtemisStackedBarChartProps {
  className?: string;
}
export function ArtemisStackedBarChart({ className }: ArtemisStackedBarChartProps) {
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <Variant0 />
    </ArtemisScope>
  );
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useRef, useState } from "react";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_SWAP } from "../../../lib/ease";
const SERIES = [
    { key: "web", label: "Web", color: "art:bg-blue-500" },
    { key: "mobile", label: "Mobile", color: "art:bg-orange-500" },
    { key: "api", label: "API", color: "art:bg-teal-500" },
] as const;
type SeriesKey = (typeof SERIES)[number]["key"];
const DAYS: readonly [
    number,
    number,
    number
][] = [
    [4200, 3100, 1800],
    [4829, 4036, 2658],
    [5385, 3938, 2685],
    [5808, 4721, 2655],
    [6061, 4399, 2552],
    [6135, 4925, 2372],
    [6052, 4356, 2925],
    [5862, 3707, 2632],
    [5632, 4008, 2322],
    [4356, 3355, 2027],
    [4263, 3758, 1775],
    [4323, 3293, 2390],
    [4561, 3941, 2280],
    [4972, 3735, 2245],
    [5519, 3631, 2268],
    [6145, 4564, 2325],
    [6777, 4522, 3184],
];
const PROJECTED = [11000, 11000, 11000, 11000];
const COUNT = DAYS.length + PROJECTED.length;
const TODAY = DAYS.length - 1;
const DOMAIN = 17243.28;
const TARGET = 12000;
const k = (v: number) => `${(v / 1000).toFixed(1)}k`;
const pct = (v: number) => `${Number(v.toFixed(4))}%`;
const BAR = "art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:relative art:flex art:h-full art:min-w-0 art:flex-1 art:items-end art:disabled:opacity-100 art:rounded-full";
const LEGEND = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:h-8 art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:transition-opacity";
const DIM = { duration: 0.18, ease: "easeOut" } as const;
const TIP_EXIT = { duration: 0.14, ease: [0.4, 0, 1, 1] } as const;
export default function ChartsStackedBar() {
    const reduce = useReducedMotion();
    const [hidden, setHidden] = useState<ReadonlySet<SeriesKey>>(new Set());
    const [active, setActive] = useState<number | null>(null);
    const bars = useRef<(HTMLButtonElement | null)[]>([]);
    const visible = SERIES.map((s) => !hidden.has(s.key));
    const totalOf = (day: readonly number[]) => day.reduce((sum, v, i) => sum + (visible[i] ? v : 0), 0);
    const grow = (i: number) => (reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_LAYOUT, delay: 0.3 + i * 0.018 });
    const toggle = (key: SeriesKey) => setHidden((prev) => {
        const next = new Set(prev);
        if (next.has(key))
            next.delete(key);
        else if (SERIES.length - prev.size > 1)
            next.add(key);
        return next;
    });
    const onBarKey = (e: KeyboardEvent<HTMLButtonElement>, i: number) => {
        const to = e.key === "ArrowRight" ? Math.min(TODAY, i + 1) : e.key === "ArrowLeft" ? Math.max(0, i - 1) : e.key === "Home" ? 0 : e.key === "End" ? TODAY : null;
        if (to === null)
            return;
        e.preventDefault();
        bars.current[to]?.focus();
    };
    const tip = active === null ? null : (() => {
        const day = DAYS[active];
        const total = totalOf(day);
        const left = ((active + 0.5) / COUNT) * 100;
        return { day, total, left, top: Math.min(48, (1 - total / DOMAIN) * 100 - 4), flip: left > 55 };
    })();
    const roving = active ?? TODAY;
    return (<>
      <div className="art:mx-auto art:w-full art:max-w-3xl">
        <figure aria-label="Requests per day" className="art:m-0 art:w-full art:pt-6">
          <div className="art:relative art:h-56">
            <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-x-0 art:z-10 art:border-foreground/30 art:border-t art:border-dashed" style={{ bottom: `${(TARGET / DOMAIN) * 100}%` }}>
              <span className="art:absolute art:-top-6 art:right-0 art:rounded-full art:border art:border-border art:bg-background art:px-2 art:py-0.5 art:text-muted-foreground art:text-xs">{"Target 12k"}</span>
            </div>
            <AnimatePresence>
              {tip && active !== null && (<motion.div key="tip" aria-hidden="true" className="art:pointer-events-none art:absolute art:z-20" initial={{ opacity: 0, left: pct(tip.left), top: pct(tip.top) }} animate={{ opacity: 1, left: pct(tip.left), top: pct(tip.top) }} exit={{ opacity: 0, transition: reduce ? { duration: 0 } : TIP_EXIT }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_SWAP}>
                  <motion.div className="art:w-48 art:rounded-2xl art:border art:border-border art:bg-background art:p-3" style={{ marginLeft: tip.flip ? -14 : 14, originX: tip.flip ? 1 : 0 }} initial={{ scale: 0.96, x: tip.flip ? "-100%" : 0 }} animate={{ scale: 1, x: tip.flip ? "-100%" : 0 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_SWAP}>
                    <div className="art:flex art:items-baseline art:justify-between art:gap-2">
                      <p className="art:font-medium art:text-sm">{`Mar ${active + 1}`}</p>
                      <p className="art:font-mono art:text-xs art:tabular-nums">{k(tip.total)}</p>
                    </div>
                    <ul className="art:mt-2 art:space-y-1">
                      {SERIES.map((s, i) => visible[i] ? (<li key={s.key} className="art:flex art:items-center art:justify-between art:gap-2 art:text-xs">
                            <span className="art:flex art:items-center art:gap-1.5 art:text-muted-foreground">
                              <span className={`art:size-1.5 art:rounded-full ${s.color}`}/>
                              {s.label}
                            </span>
                            <span className="art:font-mono art:tabular-nums">{k(tip.day[i])}</span>
                          </li>) : null)}
                    </ul>
                  </motion.div>
                </motion.div>)}
            </AnimatePresence>
            <div className="art:flex art:h-full art:items-end art:gap-1" onPointerLeave={() => setActive(null)}>
              {DAYS.map((day, i) => {
            const total = totalOf(day);
            const on = active === i;
            return (<button key={`day-${i + 1}`} ref={(el) => {
                    bars.current[i] = el;
                }} type="button" className={BAR} tabIndex={roving === i ? 0 : -1} aria-label={`Mar ${i + 1}: ${k(total)}`} aria-pressed={on} onPointerEnter={() => setActive(i)} onFocus={() => setActive(i)} onBlur={() => setActive((a) => (a === i ? null : a))} onKeyDown={(e) => onBarKey(e, i)}>
                    <span aria-hidden="true" className={`art:pointer-events-none art:absolute art:inset-y-0 art:left-1/2 art:w-px art:-translate-x-1/2 art:bg-foreground/15 art:transition-opacity art:duration-150 ${on ? "art:opacity-100" : "art:opacity-0"}`}/>
                    <motion.span aria-hidden="true" className="art:relative art:flex art:h-full art:w-full art:flex-col-reverse art:overflow-hidden art:rounded-md" style={{ originY: 1 }} initial={{ scaleY: 0, opacity: 1 }} animate={{ scaleY: total / DOMAIN, opacity: active !== null && !on ? 0.35 : 1 }} transition={{ scaleY: grow(i), opacity: reduce ? { duration: 0 } : DIM }}>
                      {SERIES.map((s, si) => (<motion.span key={s.key} className={`art:block art:w-full ${s.color}`} style={{ flexBasis: 0 }} initial={false} animate={{ flexGrow: visible[si] ? day[si] : 0, opacity: 1 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}/>))}
                    </motion.span>
                  </button>);
        })}
              {PROJECTED.map((v, j) => {
            const i = DAYS.length + j;
            return (<button key={`day-${i + 1}`} type="button" className={BAR} disabled tabIndex={-1} aria-label={`Mar ${i + 1}, projected ${k(v)}`} aria-pressed="false">
                    <span aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-y-0 art:left-1/2 art:w-px art:-translate-x-1/2 art:bg-foreground/15 art:transition-opacity art:duration-150 art:opacity-0"/>
                    <motion.span aria-hidden="true" className="art:relative art:flex art:h-full art:w-full art:flex-col-reverse art:overflow-hidden art:rounded-md art:border art:border-foreground/25 art:border-dashed" style={{ originY: 1 }} initial={{ scaleY: 0, opacity: 1 }} animate={{ scaleY: v / DOMAIN, opacity: 1 }} transition={{ scaleY: grow(i), opacity: reduce ? { duration: 0 } : DIM }}/>
                  </button>);
        })}
            </div>
          </div>
          <div aria-hidden="true" className="art:relative art:mt-3 art:h-4 art:font-mono art:text-muted-foreground art:text-xs">
            <span className="art:absolute art:top-0 art:whitespace-nowrap art:left-0">{"Mar 1"}</span>
            <span className="art:absolute art:top-0 art:whitespace-nowrap art:-translate-x-1/2 art:text-foreground" style={{ left: `${((TODAY + 0.5) / COUNT) * 100}%` }}>
              {"Today"}
            </span>
            <span className="art:absolute art:top-0 art:whitespace-nowrap art:right-0">{"Mar 21"}</span>
          </div>
        </figure>
        <div className="art:flex art:flex-wrap art:gap-2 art:mt-6">
          {SERIES.map((s) => {
            const off = hidden.has(s.key);
            const last = !off && SERIES.length - hidden.size === 1;
            return (<motion.button key={s.key} type="button" className={`${LEGEND}${off ? " art:opacity-50" : ""} art:rounded-full`} aria-pressed={!off} aria-disabled={last || undefined} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} onClick={() => !last && toggle(s.key)}>
                <span className={`art:size-2 art:rounded-full art:transition-transform art:duration-200 ${s.color}${off ? " art:scale-50" : ""}`}/>
                {s.label}
              </motion.button>);
        })}
        </div>
      </div>
    </>);
}
